mapper.select:
SELECT 
FROM ai_orchestration_state
WHERE session_id = #{sessionId} AND state_key = #{stateKey}

mapper.update:
UPDATE ai_orchestration_state
SET state_value = #{stateValue, jdbcType=LONGVARCHAR},
    version = version + 1,
    updated_by = #{updatedBy, jdbcType=BIGINT},
    updated_at = NOW()
WHERE session_id = #{sessionId}
  AND state_key = #{stateKey}
  AND version = #{version}
